 def longestSubstring(self, s):
     vowels = set('aeiou')
     n = len(s)

     prefix = [0]*(n+1)
     for i in range(n):
         if s[i] in vowels:
             prefix[i+1] = prefix[i] - 2
         else:
             prefix[i+1] = prefix[i] + 1

     stack = []
     for i in range(n+1):
